let handles: Vec<_> = (0..workers)
    .map(|w| {
        thread::spawn(move || {
            let mut local = 0u64;
            for n in chunk(w) {
                if is_prime(n) {
                    local += 1;
                }
            }
            local
        })
    })
    .collect();
let total: u64 = handles.into_iter().map(|h| h.join().unwrap()).sum();

