int m[1024][1024];
long sum = 0;

/* row by row: consecutive addresses */
for (int i = 0; i < 1024; i++)
    for (int j = 0; j < 1024; j++)
        sum += m[i][j];

/* column by column: jumps of 4096 bytes */
for (int j = 0; j < 1024; j++)
    for (int i = 0; i < 1024; i++)
        sum += m[i][j];

